import{_ as t,o,c as a,al as i}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"Test MC_11 - Companion Computer (ROS 2 External Mode)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/test_cards/mc_11_companion_ros2_external_mode.md","filePath":"zh/test_cards/mc_11_companion_ros2_external_mode.md"}'),n={name:"zh/test_cards/mc_11_companion_ros2_external_mode.md"};function r(s,e,l,p,h,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="test-mc-11-companion-computer-ros-2-external-mode" tabindex="-1">Test MC_11 - Companion Computer (ROS 2 External Mode) <a class="header-anchor" href="#test-mc-11-companion-computer-ros-2-external-mode" aria-label="Permalink to &quot;Test MC_11 - Companion Computer (ROS 2 External Mode)&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>To test autonomous flight commanded from a companion computer using the <a href="./../ros2/px4_ros2_interface_lib">PX4 ROS 2 Interface Library</a> over the <a href="./../middleware/uxrce_dds">uXRCE-DDS</a> or <a href="./../middleware/zenoh">Zenoh</a> bridge.</p><p>The test runs the library&#39;s <a href="https://github.com/Auterion/px4-ros2-interface-lib/tree/main/examples/cpp/modes/goto" target="_blank" rel="noreferrer">go-to example</a>, which registers an external flight mode named <em>Go-to Example</em> and flies a fixed triangular pattern (about 20 m x 30 m) relative to the position where the mode is engaged, at constant altitude. This exercises external mode registration, setpoint configuration, go-to setpoint streaming, and mode completion signalling across the bridge.</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Companion computer setup (once):</p><ul><li>Connect a companion computer to the flight controller and start the bridge: <ul><li><a href="./../middleware/uxrce_dds">uXRCE-DDS</a>: run the micro XRCE-DDS agent on the companion computer, or</li><li><a href="./../middleware/zenoh">Zenoh</a>: follow the ROS 2 Zenoh bring-up on the companion computer</li></ul></li><li>Set up a ROS 2 workspace on the companion computer with <code>px4_msgs</code> and the interface library, following steps 1 to 3 of <a href="./../ros2/px4_ros2_control_interface#installation-and-first-test">PX4 ROS 2 Control Interface &gt; Installation and First Test</a> (skip the SITL steps). The go-to example is built as part of the workspace (package <code>example_mode_goto_cpp</code>).</li><li>Use a recent QGroundControl (Daily), which supports dynamically updating the list of flight modes.</li></ul><p>Before flight:</p><ul><li><p>Start the example on the companion computer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example_mode_goto_cpp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example_mode_goto</span></span></code></pre></div></li><li><p>Confirm the console shows the registration succeeding (<code>Registering &#39;Go-to Example&#39;</code> followed by <code>Got RegisterExtComponentReply</code>)</p></li><li><p>Confirm <em>Go-to Example</em> shows up in the QGC flight mode list</p></li><li><p>Confirm the airspace is clear roughly 20 m north and 30 m east of the planned engage position (the pattern is flown from wherever the mode is engaged)</p></li></ul><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ Mode registration</p><p>    ❏ With the vehicle disarmed, stop and restart the example node</p><p>    ❏ <em>Go-to Example</em> disappears from and reappears in the QGC mode list</p><p>❏ Go-to Example mode</p><p>    ❏ Arm and take off in Position mode, climb to a safe altitude (10 m or more)</p><p>    ❏ Select <em>Go-to Example</em> in QGC (mode must engage on first attempt, no rejection message)</p><p>    ❏ Vehicle settles at the engage position, then flies north facing the direction of travel</p><p>    ❏ Vehicle flies the east leg while spinning around yaw, slowing down as it approaches the corner</p><p>    ❏ Vehicle returns to the engage position with the heading fixed on the first corner</p><p>    ❏ On completion the vehicle holds position; switch back to Position or Hold mode</p><p>❏ Re-engagement</p><p>    ❏ Fly to a different location and engage <em>Go-to Example</em> again</p><p>    ❏ The same pattern is flown relative to the new engage position</p><p>❏ Companion loss failsafe</p><p>    ❏ Engage <em>Go-to Example</em> once more and stop the example node (Ctrl-C) mid-pattern</p><p>    ❏ Vehicle triggers a failsafe and switches to Hold; QGC shows a corresponding warning</p><p>❏ Land and disarm</p><h2 id="预期成果" tabindex="-1">预期成果 <a class="header-anchor" href="#预期成果" aria-label="Permalink to &quot;预期成果&quot;">​</a></h2><ul><li>The external mode appears in QGC while the node is running and can be engaged on the first attempt</li><li>Transitions into and out of the mode are smooth, with no twitches or setpoint jumps</li><li>The triangular pattern is tracked accurately at constant altitude</li><li>Stopping the node while the mode is active triggers a failsafe into Hold</li><li>The log shows the pattern portion of the flight in the external mode (check in <a href="./../log/flight_review">Flight Review</a>)</li><li>Attach the flight log and the example&#39;s console output to the test report</li></ul>',29)])])}const g=t(n,[["render",r]]);export{c as __pageData,g as default};
